// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    ValidSigner signer;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        signer = new ValidSigner();
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce,
        uint256 expiresIn
    ) public {
        strike = bound(strike, 0, type(uint256).max);
        premium = bound(premium, 0, type(uint256).max);
        duration = bound(duration, 0, 10_000 days - 1);
        nonce = bound(nonce, 0, type(uint256).max);
        expiresIn = bound(expiresIn, 1, 10_000 days);

        address[] memory emptyAddrs = new address[](0);
        PuttyV2.ERC20Asset[] memory noErc20 = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory noErc721 = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(signer),
            isCall: true,
            isLong: false,
            baseAsset: address(signer),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + expiresIn,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorIds = new uint256[](0);

        uint256 positionId = 0;
        bool filled = false;
        try c.fillOrder(order, sig, floorIds) returns (uint256 pid) {
            filled = true;
            positionId = pid;
        } catch {
            filled = false;
        }

        // General rule: for any admissible order, a successful fill makes the
        // taker (msg.sender) the owner of the minted opposite-position token.
        // The buggy _mint assigns address(0), so ownerOf reverts (NOT_MINTED).
        bool takerOwnsPosition = true;
        if (filled) {
            try c.ownerOf(positionId) returns (address owner_) {
                takerOwnsPosition = (owner_ == address(this));
            } catch {
                takerOwnsPosition = false;
            }
        }

        assertTrue(filled ? takerOwnsPosition : true, "taker must own minted position");
    }
}

contract ValidSigner {
    // Accepts EIP-1271 signature checks used by the order maker, and acts as
    // a permissive baseAsset ERC20 (fallback returns success for any call).
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    fallback() external payable {}
}
